// request.getReader() - zwraca BufferedReader do czytania ciala
// zadania jako TEKST (z odpowiednim dekodowaniem znakow).
// request.getInputStream() - zwraca ServletInputStream do czytania
// ciala jako SUROWE BAJTY - potrzebne dla tresci binarnych.

// UWAGA: mozna wywolac TYLKO JEDNO z tych dwoch na tym samym
// zadaniu - wywolanie drugiego po pierwszym rzuci
// IllegalStateException, bo oba czytaja z tego samego,
// jednorazowego strumienia danych.

try (BufferedReader reader = req.getReader()) {
    String line;
    while ((line = reader.readLine()) != null) {
        out.append(line).append("\n");
    }
}

out.append("== Parametry (getParameter) ==\n");
out.append("imie = ").append(req.getParameter("imie")).append("\n");

out.append("\n== Parametry (getParameterMap) ==\n");
for (var entry : req.getParameterMap().entrySet()) {
    out.append(entry.getKey()).append(" = ")
            .append(String.join(",", entry.getValue())).append("\n");
}

out.append("\n== Naglowki ==\n");
Enumeration<String> headerNames = req.getHeaderNames();
for (String name : Collections.list(headerNames)) {
    out.append(name).append(": ").append(req.getHeader(name)).append("\n");
}
